public final class ReportTest {
    public static void main(String[] args) {
        checkSmall();
        checkEmpty();
        checkPerformance();
        System.out.println("all tests passed");
    }

    static void checkSmall() {
        String got = Report.joinLines(new String[] {"a", "b", "c"});
        if (!got.equals("a\nb\nc\n")) {
            throw new AssertionError("joinLines([a,b,c]) = " + got.replace("\n", "\\n")
                    + ", expected a\\nb\\nc\\n (every line newline-terminated)");
        }
    }

    static void checkEmpty() {
        if (!Report.joinLines(new String[0]).equals("")) {
            throw new AssertionError("empty input must give an empty string");
        }
    }

    static void checkPerformance() {
        int n = 120000;
        String[] lines = new String[n];
        for (int i = 0; i < n; i++) {
            lines[i] = "line number " + i;
        }
        long start = System.nanoTime();
        String out = Report.joinLines(lines);
        double elapsed = (System.nanoTime() - start) / 1e9;

        if (!out.startsWith("line number 0\n") || !out.endsWith("line number 119999\n")) {
            throw new AssertionError("large join content wrong");
        }
        // calibrated: += in the loop is ~7.5s on fast native hardware and
        // slower in the sandbox; StringBuilder is ~0.005s
        if (elapsed >= 2.5) {
            throw new AssertionError(String.format(
                    "joinLines took %.2fs for %d lines; expected a StringBuilder, "
                    + "not String += which copies the whole accumulator every iteration",
                    elapsed, n));
        }
    }
}

