public final class Report {
    private Report() {}

    /** All lines joined, each terminated by a newline. */
    public static String joinLines(String[] lines) {
        StringBuilder sb = new StringBuilder();
        for (String line : lines) {
            sb.append(line).append('\n');
        }
        return sb.toString();
    }
}

